 CAB.push(...[["science", "🔬", "Science", [["Physics", [["Newton's laws of motion", "An object keeps its motion unless a force acts on it; force equals mass times acceleration (F = ma); every action has an equal and opposite reaction.", "Wikipedia: Newton's laws of motion", "https://en.wikipedia.org/wiki/Newton%27s_laws_of_motion"], ["Energy", "The capacity to do work, measured in joules. It changes form (motion, heat, light, chemical), but the total in a closed system stays the same.", "Wikipedia: Energy", "https://en.wikipedia.org/wiki/Conservation_of_energy"], ["Speed of light", "About 299,792 kilometres a second in a vacuum, the fastest anything can travel. Sunlight takes about 8 minutes 20 seconds to reach Earth.", "Wikipedia: Speed of light", "https://en.wikipedia.org/wiki/Speed_of_light"], ["Gravity", "The pull every mass has on every other. Near Earth's surface it speeds a falling object up by about 9.8 metres a second, every second.", "Wikipedia: Gravity", "https://en.wikipedia.org/wiki/Gravity"], ["Sound", "A pressure wave travelling through air, water or solids. In air at 20 °C it moves about 343 metres a second; its frequency is heard as pitch.", "Wikipedia: Sound", "https://en.wikipedia.org/wiki/Sound"]]], ["Chemistry", [["Atom", "The smallest unit of an element: a nucleus of protons and neutrons with electrons around it. The number of protons, the atomic number, decides the element.", "Wikipedia: Atom", "https://en.wikipedia.org/wiki/Atom"], ["Periodic table", "The elements in order of atomic number, in rows (periods) and columns (groups); elements in the same column behave alike. 118 elements have names.", "Wikipedia: Periodic table", "https://en.wikipedia.org/wiki/Periodic_table"], ["Chemical bond", "Atoms held together by sharing electrons (covalent bonds) or by the pull between charged ions (ionic bonds).", "Wikipedia: Chemical bond", "https://en.wikipedia.org/wiki/Chemical_bond"], ["pH", "How acidic or basic a solution is, from 0 to 14: 7 is neutral, lower is acidic, higher is basic. Each whole step is ten times stronger.", "Wikipedia: pH", "https://en.wikipedia.org/wiki/PH"], ["States of matter", "Solid, liquid, gas and plasma. Heat moves matter between them: at sea level water melts at 0 °C and boils at 100 °C.", "Wikipedia: States of matter", "https://en.wikipedia.org/wiki/State_of_matter"]]], ["Biology", [["Cell", "The smallest living unit. Every living thing is made of one or more cells; a human body has tens of trillions.", "Wikipedia: Cell", "https://en.wikipedia.org/wiki/Cell_(biology)"], ["DNA", "The molecule that carries genetic instructions: a double helix whose four bases pair A with T and C with G.", "Wikipedia: DNA", "https://en.wikipedia.org/wiki/DNA"], ["Natural selection", "Living things vary; those whose traits suit their surroundings leave more offspring, so those traits become more common over generations.", "Wikipedia: Natural selection", "https://en.wikipedia.org/wiki/Natural_selection"], ["Photosynthesis", "Plants, algae and some bacteria use light to turn carbon dioxide and water into sugar, giving off oxygen.", "Wikipedia: Photosynthesis", "https://en.wikipedia.org/wiki/Photosynthesis"], ["Ecosystem", "The living things of a place together with their surroundings, linked by food webs and the flow of energy and nutrients.", "Wikipedia: Ecosystem", "https://en.wikipedia.org/wiki/Ecosystem"]]], ["Earth and space", [["Solar System", "The Sun and everything bound to it: eight planets (Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune), dwarf planets, moons, asteroids and comets.", "Wikipedia: Solar System", "https://en.wikipedia.org/wiki/Solar_System"], ["Plate tectonics", "Earth's outer shell is broken into plates that move a few centimetres a year; where they meet they raise mountains, shake as earthquakes and feed volcanoes.", "Wikipedia: Plate tectonics", "https://en.wikipedia.org/wiki/Plate_tectonics"], ["Water cycle", "Water evaporates, condenses into clouds, falls as rain or snow and flows back to the sea or into the ground, over and over.", "Wikipedia: Water cycle", "https://en.wikipedia.org/wiki/Water_cycle"], ["Seasons", "Earth's axis is tilted about 23.4°, so each hemisphere leans toward the Sun for half the year (summer) and away for the other half (winter).", "Wikipedia: Seasons", "https://en.wikipedia.org/wiki/Season"], ["Light-year", "The distance light travels in a year, about 9.46 trillion kilometres. The nearest star after the Sun, Proxima Centauri, is about 4.2 light-years away.", "Wikipedia: Light-year", "https://en.wikipedia.org/wiki/Light-year"]]]]], ["history", "🏛", "History", [["The ancient world", [["Cuneiform", "The first known writing, pressed into clay in Mesopotamia about 5,000 years ago (around 3200 BCE), at first to keep accounts.", "Wikipedia: Cuneiform", "https://en.wikipedia.org/wiki/Cuneiform"], ["Ancient Egypt", "A civilization along the Nile that lasted about 3,000 years; the Great Pyramid of Giza was built around 2560 BCE.", "Wikipedia: Ancient Egypt", "https://en.wikipedia.org/wiki/Ancient_Egypt"], ["Ancient Greece", "City-states such as Athens and Sparta. Athens ran an early democracy from about 508 BCE, and Greek thinkers shaped philosophy, mathematics and theatre.", "Wikipedia: Ancient Greece", "https://en.wikipedia.org/wiki/Ancient_Greece"], ["Roman Empire", "Grew from the city of Rome to rule the Mediterranean. Its western half fell in 476 CE; the eastern half, Byzantium, lasted until 1453.", "Wikipedia: Roman Empire", "https://en.wikipedia.org/wiki/Roman_Empire"], ["Silk Road", "Trade routes linking China with Central Asia, the Middle East and Europe for over 1,500 years, carrying silk, spices, ideas and religions.", "Wikipedia: Silk Road", "https://en.wikipedia.org/wiki/Silk_Road"]]], ["Middle ages to early modern", [["Printing press", "Johannes Gutenberg's movable-type press, about 1440 in Mainz, made books cheap enough to spread learning across Europe.", "Wikipedia: Printing press", "https://en.wikipedia.org/wiki/Printing_press"], ["Renaissance", "A rebirth of art and learning that began in Italy in the 14th century: Leonardo da Vinci, Michelangelo and the study of classical texts.", "Wikipedia: Renaissance", "https://en.wikipedia.org/wiki/Renaissance"], ["Age of Discovery", "From the 15th to the 17th century European sailors crossed the oceans: Columbus reached the Americas in 1492, and Magellan's expedition first sailed around the world (1519 to 1522).", "Wikipedia: Age of Discovery", "https://en.wikipedia.org/wiki/Age_of_Discovery"], ["Scientific Revolution", "In the 16th and 17th centuries Copernicus, Galileo and Newton replaced old ideas with observation, experiment and mathematics.", "Wikipedia: Scientific Revolution", "https://en.wikipedia.org/wiki/Scientific_Revolution"]]], ["The modern world", [["Industrial Revolution", "From about 1760 in Britain, machines, steam power and factories changed how goods were made and where people lived.", "Wikipedia: Industrial Revolution", "https://en.wikipedia.org/wiki/Industrial_Revolution"], ["World War I", "1914 to 1918, fought mainly in Europe; millions of soldiers and civilians died, and four empires fell.", "Wikipedia: World War I", "https://en.wikipedia.org/wiki/World_War_I"], ["World War II", "1939 to 1945, the deadliest war in history, with an estimated 70 to 85 million deaths.", "Wikipedia: World War II", "https://en.wikipedia.org/wiki/World_War_II"], ["Apollo 11", "On 20 July 1969 Apollo 11 landed on the Moon, and Neil Armstrong and Buzz Aldrin walked on its surface.", "Wikipedia: Apollo 11", "https://en.wikipedia.org/wiki/Apollo_11"], ["History of the Internet", "It grew from ARPANET (1969); the World Wide Web, invented by Tim Berners-Lee in 1989, made linking pages easy.", "Wikipedia: History of the Internet", "https://en.wikipedia.org/wiki/History_of_the_Internet"]]], ["How to read history", [["Primary source", "Evidence made at the time: a letter, a photograph, a diary, a law.", "Wikipedia: Primary source", "https://en.wikipedia.org/wiki/Primary_source"], ["Secondary source", "A later work that explains or weighs primary sources, such as a history book.", "Wikipedia: Secondary source", "https://en.wikipedia.org/wiki/Secondary_source"], ["Common Era", "BCE and CE (Before the Common Era, Common Era) count the same years as BC and AD. There is no year 0: 1 BCE is followed by 1 CE.", "Wikipedia: Common Era", "https://en.wikipedia.org/wiki/Common_Era"], ["Chronology", "Putting events in order of time. A timeline shows cause and effect more clearly than a list.", "Wikipedia: Chronology", "https://en.wikipedia.org/wiki/Chronology"]]]]], ["art", "🎨", "Art & design", [["Color", [["Color wheel", "Colors arranged in a circle by hue. Red, yellow and blue are the painter's traditional primaries; screens mix red, green and blue light.", "Wikipedia: Color wheel", "https://en.wikipedia.org/wiki/Color_wheel"], ["Complementary colors", "Colors opposite each other on the wheel, such as blue and orange; side by side they make each other look stronger.", "Wikipedia: Complementary colors", "https://en.wikipedia.org/wiki/Complementary_colors"], ["HSL and HSV", "Hue is the color itself, saturation how pure or grey it is, and lightness or value how light or dark it is.", "Wikipedia: HSL and HSV", "https://en.wikipedia.org/wiki/HSL_and_HSV"], ["Color theory", "Reds, oranges and yellows feel warm and seem to come forward; blues and greens feel cool and seem to sit back.", "Wikipedia: Color theory", "https://en.wikipedia.org/wiki/Color_theory"]]], ["Composition", [["Rule of thirds", "Divide the frame into a 3 × 3 grid and place the subject on a line or a crossing; it usually feels livelier than dead centre.", "Wikipedia: Rule of thirds", "https://en.wikipedia.org/wiki/Rule_of_thirds"], ["Contrast (vision)", "A difference in light, color, size or texture draws the eye; people look first where the contrast is strongest.", "Wikipedia: Contrast", "https://en.wikipedia.org/wiki/Contrast_(vision)"], ["Negative space", "The empty space around a subject. It gives the subject room and can form shapes of its own.", "Wikipedia: Negative space", "https://en.wikipedia.org/wiki/Negative_space"], ["Visual hierarchy", "Size, weight, color and position tell the viewer what to look at first, second and third.", "Wikipedia: Visual hierarchy", "https://en.wikipedia.org/wiki/Visual_hierarchy"]]], ["Typography", [["Serif", "Serif typefaces have small strokes at the ends of letters; sans-serif faces do not.", "Wikipedia: Serif", "https://en.wikipedia.org/wiki/Serif"], ["Kerning", "The space between two letters. Leading is the space between lines.", "Wikipedia: Kerning", "https://en.wikipedia.org/wiki/Kerning"], ["Line length", "Lines of about 45 to 75 characters are the easiest to read.", "Wikipedia: Line length", "https://en.wikipedia.org/wiki/Line_length"], ["Typeface", "A family of letter designs; a font is one size and weight of it.", "Wikipedia: Typeface", "https://en.wikipedia.org/wiki/Typeface"]]], ["Art movements", [["Impressionism", "Late 19th-century French painting that caught light and the passing moment with loose brushwork: Monet, Renoir, Morisot.", "Wikipedia: Impressionism", "https://en.wikipedia.org/wiki/Impressionism"], ["Cubism", "From about 1907, Picasso and Braque painted objects from several viewpoints at once, broken into planes.", "Wikipedia: Cubism", "https://en.wikipedia.org/wiki/Cubism"], ["Surrealism", "From the 1920s, dream images and unexpected combinations: Dalí and Magritte. Frida Kahlo is often linked with it, though she said she painted her own reality.", "Wikipedia: Surrealism", "https://en.wikipedia.org/wiki/Surrealism"], ["Pop art", "From the 1950s, images borrowed from advertising and comics: Warhol, Lichtenstein.", "Wikipedia: Pop art", "https://en.wikipedia.org/wiki/Pop_art"]]]]], ["tech", "💻", "Technology & code", [["How computers work", [["Byte", "A bit is a single 0 or 1; a byte is 8 bits, enough for 256 different values.", "Wikipedia: Byte", "https://en.wikipedia.org/wiki/Byte"], ["Central processing unit", "The processor that follows a program's instructions, billions of steps a second.", "Wikipedia: Central processing unit", "https://en.wikipedia.org/wiki/Central_processing_unit"], ["Computer data storage", "Memory (RAM) holds what is being worked on and is cleared when the power goes off; storage, such as a drive, keeps files.", "Wikipedia: Computer data storage", "https://en.wikipedia.org/wiki/Computer_data_storage"], ["Operating system", "The software that runs the computer and shares it among programs: Windows, macOS, Linux, Android, iOS.", "Wikipedia: Operating system", "https://en.wikipedia.org/wiki/Operating_system"]]], ["The web", [["URL", "A page's address: the scheme (https), the domain (example.com) and the path to the page.", "Wikipedia: URL", "https://en.wikipedia.org/wiki/URL"], ["HTML", "HTML gives a web page its structure, CSS its look and JavaScript its behaviour. KAN-IN is built from all three.", "Wikipedia: HTML", "https://en.wikipedia.org/wiki/HTML"], ["HTTPS", "The secure way a browser and a website talk; the padlock means the connection is encrypted.", "Wikipedia: HTTPS", "https://en.wikipedia.org/wiki/HTTPS"], ["Web storage", "A website can keep small amounts of data in your browser, such as your saved work, which stays on that device.", "Wikipedia: Web storage", "https://en.wikipedia.org/wiki/Web_storage"]]], ["Programming basics", [["Variable (computer science)", "A named box that holds a value, such as score = 10.", "Wikipedia: Variable", "https://en.wikipedia.org/wiki/Variable_(computer_science)"], ["Control flow", "Loops repeat instructions a set number of times or until a condition is met; if statements choose between paths.", "Wikipedia: Control flow", "https://en.wikipedia.org/wiki/Control_flow"], ["Function (computer programming)", "A named set of instructions you can run again and again, often taking inputs and giving back a result.", "Wikipedia: Function", "https://en.wikipedia.org/wiki/Function_(computer_programming)"], ["Algorithm", "A step-by-step method for solving a problem, which a computer can follow exactly.", "Wikipedia: Algorithm", "https://en.wikipedia.org/wiki/Algorithm"], ["Software bug", "A mistake that makes a program do the wrong thing; finding and fixing it is debugging.", "Wikipedia: Software bug", "https://en.wikipedia.org/wiki/Software_bug"]]], ["AI basics", [["Machine learning", "Programs that learn patterns from examples instead of following only hand-written rules.", "Wikipedia: Machine learning", "https://en.wikipedia.org/wiki/Machine_learning"], ["Language model", "An AI trained on large amounts of text to predict and write language. It can be wrong, so check what matters.", "Wikipedia: Language model", "https://en.wikipedia.org/wiki/Language_model"], ["Training data", "The examples a model learns from; what is missing or lopsided there shows up in its answers.", "Wikipedia: Training data", "https://en.wikipedia.org/wiki/Training,_validation,_and_test_data_sets"], ["Prompt engineering", "How you ask an AI: a clear goal, context and an example of what you want give better answers.", "Wikipedia: Prompt engineering", "https://en.wikipedia.org/wiki/Prompt_engineering"]]]]], ["film", "🎬", "Film & video", [["Shots", [["Long shot", "A wide shot that shows the whole scene and where the characters stand in it.", "Wikipedia: Long shot", "https://en.wikipedia.org/wiki/Long_shot"], ["Close-up", "Fills the frame with a face or an object to show feeling or detail.", "Wikipedia: Close-up", "https://en.wikipedia.org/wiki/Close-up"], ["Point-of-view shot", "Shows what a character sees.", "Wikipedia: Point-of-view shot", "https://en.wikipedia.org/wiki/Point-of-view_shot"], ["Over the shoulder shot", "Frames one person from behind another's shoulder; common in conversations.", "Wikipedia: Over the shoulder shot", "https://en.wikipedia.org/wiki/Over_the_shoulder_shot"]]], ["Editing", [["Cut (transition)", "An instant change from one shot to the next.", "Wikipedia: Cut", "https://en.wikipedia.org/wiki/Cut_(transition)"], ["Montage (filmmaking)", "A run of short shots that squeezes time or builds a feeling.", "Wikipedia: Montage", "https://en.wikipedia.org/wiki/Montage_(filmmaking)"], ["180-degree rule", "Keep the camera on one side of the line between two characters, so each stays on the same side of the frame.", "Wikipedia: 180-degree rule", "https://en.wikipedia.org/wiki/180-degree_rule"], ["Frame rate", "Pictures shown each second: 24 is the film standard; 30 and 60 are common for video.", "Wikipedia: Frame rate", "https://en.wikipedia.org/wiki/Frame_rate"]]], ["Sound for picture", [["Diegesis", "Diegetic sound exists in the story's world, such as dialogue or a car horn; music only the audience hears is non-diegetic.", "Wikipedia: Diegesis", "https://en.wikipedia.org/wiki/Diegesis"], ["Foley (filmmaking)", "Everyday sounds recorded in a studio to match the picture: footsteps, cloth, doors.", "Wikipedia: Foley", "https://en.wikipedia.org/wiki/Foley_(filmmaking)"], ["Room tone", "A recording of a place's quiet, laid under edits so the gaps do not sound empty.", "Wikipedia: Room tone", "https://en.wikipedia.org/wiki/Room_tone"]]]]], ["money", "💵", "Money & business", [["Money basics", [["Budget", "A plan for the money coming in and going out, so spending follows what matters to you.", "Wikipedia: Budget", "https://en.wikipedia.org/wiki/Budget"], ["Compound interest", "Simple interest is paid on the starting amount only; compound interest is paid on the interest too, so growth speeds up over time.", "Wikipedia: Compound interest", "https://en.wikipedia.org/wiki/Compound_interest"], ["Inflation", "The general rise in prices over time, so the same money buys less.", "Wikipedia: Inflation", "https://en.wikipedia.org/wiki/Inflation"], ["Saving", "Money set aside instead of spent, often kept for surprises such as a repair.", "Wikipedia: Saving", "https://en.wikipedia.org/wiki/Saving"]]], ["Business basics", [["Profit (accounting)", "Revenue is money taken in, cost is money spent, and profit is revenue minus cost.", "Wikipedia: Profit", "https://en.wikipedia.org/wiki/Profit_(accounting)"], ["Supply and demand", "When more people want something than there is, its price tends to rise; when there is more than people want, it tends to fall.", "Wikipedia: Supply and demand", "https://en.wikipedia.org/wiki/Supply_and_demand"], ["Brand", "The name, look and promise that set a product apart.", "Wikipedia: Brand", "https://en.wikipedia.org/wiki/Brand"], ["Copyright", "A creator's right to control copies of an original work, such as a story, a song or a drawing.", "Wikipedia: Copyright", "https://en.wikipedia.org/wiki/Copyright"]]]]]]); /* v229: six more cabinets */
